package com.ruoyi.framework.audit;
import java.util.*;import java.nio.file.*;import java.time.*;import com.alibaba.fastjson2.JSON;import org.springframework.stereotype.Component;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.*;import org.springframework.transaction.PlatformTransactionManager;import com.ruoyi.common.utils.SecurityUtils;
@Component public class AuditRecorder {
 public final JdbcTemplate jdbc;private final TransactionTemplate independent;
 public AuditRecorder(JdbcTemplate jdbc,PlatformTransactionManager manager){this.jdbc=jdbc;independent=new TransactionTemplate(manager);independent.setPropagationBehavior(3);}
 public void actor(AuditContext c){try{var u=SecurityUtils.getLoginUser();c.actorId=u.getUserId();c.actor=u.getUsername();c.actorName=u.getUser().getNickName();var rows=jdbc.queryForList("SELECT factory_id FROM sys_user WHERE user_id=?",c.actorId);if(!rows.isEmpty()&&rows.get(0).get("factory_id")!=null)c.actorFactory=((Number)rows.get(0).get("factory_id")).longValue();}catch(Exception ignored){}}
 private String table(AuditContext c){String path=c.path;if(path.equals("/metal/volume-rule"))return "metal_factory_volume_rule";if(path.equals("/metal/process/types"))return "metal_process_type";if(path.equals("/metal/customer")||path.startsWith("/metal/customer/"))return "metal_customer";if(path.equals("/metal/metal-types"))return "metal_type";if(path.equals("/metal/inventory/opening"))return "metal_warehouse_order";if((path.startsWith("/metal/product/")||path.equals("/metal/product")))return "metal_product";if(path.startsWith("/metal/material"))return "metal_material";if(path.startsWith("/metal/process/" )||path.equals("/metal/process"))return "metal_process";if(path.startsWith("/metal/quote-rule"))return "metal_type_quote_rule";if(path.startsWith("/metal/work-order"))return "metal_work_order";if(path.equals("/metal/warehouse-flows")||path.startsWith("/metal/warehouse-flows/"))return "metal_warehouse_flow";if(path.equals("/metal/acid-wash")||path.startsWith("/metal/acid-wash/"))return "metal_acid_wash_batch";if(path.startsWith("/metal/warehouse-order"))return "metal_warehouse_order";if(path.startsWith("/metal/inventory"))return "metal_inventory";if(path.startsWith("/metal/process-batch"))return "metal_process_batch";if(path.startsWith("/metal/warning-record"))return "metal_warning_record";if(path.startsWith("/metal/warehouse/" )||path.equals("/metal/warehouse"))return "metal_warehouse";if(path.startsWith("/metal/factory"))return "metal_factory";if(path.startsWith("/metal/production-line"))return "metal_production_line";if(path.equals("/metal/quotation/save")||path.startsWith("/metal/quotation/orders"))return "metal_saved_quotation";if(path.startsWith("/system/user"))return "sys_user";if(path.startsWith("/system/role"))return "sys_role";return null;}
 private String pk(String table){return switch(table){case "metal_factory_volume_rule"->"factory_id";case "metal_process_type"->"type_id";case "metal_customer"->"customer_id";case "metal_type"->"metal_type_id";case "metal_type_quote_rule"->"metal_type_id";case "metal_product"->"product_id";case "metal_material"->"material_id";case "metal_process"->"process_id";case "metal_quote_rule","metal_volume_rule"->"rule_id";case "metal_work_order"->"work_order_id";case "metal_warehouse_order"->"order_id";case "metal_saved_quotation"->"quote_id";case "metal_inventory"->"inventory_id";case "metal_process_batch"->"batch_id";case "metal_acid_wash_batch"->"acid_wash_id";case "metal_warehouse_flow"->"flow_id";case "metal_warning_record"->"warning_id";case "metal_warehouse"->"warehouse_id";case "metal_factory"->"factory_id";case "metal_production_line"->"production_line_id";case "sys_user"->"user_id";case "sys_role"->"role_id";default->"id";};}
 public Map<String,Object> snapshot(AuditContext c,Object body,Object result){if(SemiReleaseAuditSnapshot.handles(c.path))return new SemiReleaseAuditSnapshot(jdbc).snapshot(c,body,result);String table=table(c);if(table==null)return Map.of();c.objectType=table;if(result!=null&&body instanceof com.ruoyi.metal.service.WarehouseImportService.Input input)c.factories.add(input.factoryId());Set<Long> ids=new TreeSet<>();if(body instanceof com.ruoyi.metal.catalog.MetalQuoteRule rule&&rule.metalTypeId()!=null)ids.add(rule.metalTypeId());if(c.path.startsWith("/system/user/profile"))ids.add(SecurityUtils.getUserId());boolean weightStage=c.path.matches("/metal/work-order/[0-9]+/weight-stage/[0-9]+/[0-9]+/(close|reopen)");boolean warehouseFlow=table.equals("metal_warehouse_flow");boolean multiSubmission=c.path.equals("/metal/warehouse-order/inbound-submissions")||c.path.equals("/metal/warehouse-order/outbound-submissions");String[] paths=warehouseFlow?(c.path.matches("/metal/warehouse-flows/[0-9]+(/.*)?")?new String[]{c.path.split("/")[3]}:new String[0]):weightStage?new String[]{c.path.split("/")[3]}:c.path.split("/");for(String part:paths)if(part.matches("[0-9]+(,[0-9]+)*"))for(String id:part.split(","))if(ids.size()<100)ids.add(Long.valueOf(id));try{var json=JSON.parseObject(JSON.toJSONString(body));if(multiSubmission&&result==null)ids.addAll(submissionOrderIds(c,json));for(String key:List.of("id","metalTypeId","factoryId","factoryIds")){if(key.equals("factoryId")&&!table.equals("metal_factory"))continue;if(key.equals("metalTypeId")&&!table.equals("metal_type")&&!table.equals("metal_type_quote_rule"))continue;if(json.get(key)!=null&&json.get(key).toString().matches("[0-9]+"))ids.add(Long.valueOf(json.get(key).toString()));}if(!weightStage&&!multiSubmission&&json.get("requestId")!=null&&Set.of("metal_work_order","metal_warehouse_order","metal_process_batch","metal_acid_wash_batch","metal_warehouse_flow","metal_saved_quotation").contains(table)){var rows=warehouseFlow?jdbc.queryForList("SELECT flow_id id FROM metal_warehouse_flow WHERE request_id=? UNION SELECT flow_id id FROM metal_warehouse_flow_request WHERE request_id=?",json.get("requestId"),json.get("requestId")):table.equals("metal_saved_quotation")?jdbc.queryForList("SELECT quote_id id FROM metal_quotation_request WHERE request_id=? UNION SELECT quote_id id FROM metal_saved_quotation WHERE request_id=?",json.get("requestId"),json.get("requestId")):table.equals("metal_acid_wash_batch")&&c.path.endsWith("/finish")?jdbc.queryForList("SELECT acid_wash_id id FROM metal_acid_wash_batch WHERE finish_request_id=?",json.get("requestId")):jdbc.queryForList("SELECT "+pk(table)+" id FROM "+table+" WHERE request_id=?",json.get("requestId"));rows.forEach(r->ids.add(((Number)r.get("id")).longValue()));if(result==null&&!rows.isEmpty())c.replayed=true;}}catch(Exception ignored){}if(warehouseFlow&&c.path.matches("/metal/warehouse-flows/handover/[0-9]+")){jdbc.queryForList("SELECT flow_id id FROM metal_warehouse_flow WHERE batch_id=? AND kind='HANDOVER'",Long.valueOf(c.path.substring(c.path.lastIndexOf('/')+1))).forEach(r->ids.add(((Number)r.get("id")).longValue()));}if(result instanceof Map<?,?> flowResult&&flowResult.get("flowId")!=null&&flowResult.get("flowId").toString().matches("[0-9]+")){long flowId=Long.parseLong(flowResult.get("flowId").toString());if(warehouseFlow)ids.add(flowId);else if(table.equals("metal_warehouse_order"))jdbc.queryForList("SELECT order_id id FROM metal_warehouse_order WHERE warehouse_flow_id=?",flowId).forEach(r->ids.add(((Number)r.get("id")).longValue()));}if(table.equals("metal_warehouse_order")&&result instanceof Map<?,?> submission&&submission.get("orders") instanceof List<?> orders)for(Object item:orders)if(item instanceof Map<?,?> order&&order.get("id")!=null&&order.get("id").toString().matches("[0-9]+"))ids.add(Long.valueOf(order.get("id").toString()));if(table.equals("metal_process_type")&&result instanceof Map<?,?> typed&&typed.get("id")!=null&&typed.get("id").toString().matches("[0-9]+"))ids.add(Long.valueOf(typed.get("id").toString()));if(!table.equals("metal_inventory")&&result instanceof String s&&s.matches("[0-9]+"))ids.add(Long.valueOf(s));if(table.equals("metal_saved_quotation")&&result instanceof Map<?,?> reused&&Boolean.TRUE.equals(reused.get("reused")))c.replayed=true;if(table.equals("metal_saved_quotation")&&result instanceof Map<?,?> values&&values.get("id")!=null&&values.get("id").toString().matches("[0-9]+"))ids.add(Long.valueOf(values.get("id").toString()));if(table.equals("metal_factory_volume_rule")){ids.clear();Long factory=c.actorFactory;try{var request=JSON.parseObject(c.request);var parameters=request.getJSONObject("parameters");if(parameters!=null&&parameters.getLong("factoryId")!=null)factory=parameters.getLong("factoryId");}catch(RuntimeException ignored){}if(factory!=null&&(Objects.equals(c.actorId,1L)||Objects.equals(factory,c.actorFactory)))ids.add(factory);}Map<String,Object> out=new LinkedHashMap<>();for(Long id:ids){var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE "+pk(table)+"=?",id);if(!rows.isEmpty()){var row=rows.get(0);Object f=table.equals("metal_factory")?id:row.get("factory_id");if(table.equals("metal_type_quote_rule")){var metal=jdbc.queryForList("SELECT factory_id FROM metal_type WHERE metal_type_id=?",id);f=metal.isEmpty()?null:metal.get(0).get("factory_id");}if((Set.of("metal_product","metal_material","metal_process","metal_process_type","metal_type","metal_type_quote_rule","metal_factory_volume_rule").contains(table)||weightStage||table.equals("metal_customer")||table.equals("metal_acid_wash_batch")||warehouseFlow||table.equals("metal_saved_quotation"))&&!Objects.equals(c.actorId,1L)&&(!(f instanceof Number)||!Objects.equals(c.actorFactory,((Number)f).longValue())))continue;if(f instanceof Number n)c.factories.add(n.longValue());Object code=row.getOrDefault("order_no",row.getOrDefault("batch_no",row.getOrDefault("quote_no",id)));c.businessCode=code.toString();if(table.equals("metal_product"))row.put("processes",jdbc.queryForList("SELECT * FROM metal_product_process WHERE product_id=? ORDER BY sequence_no LIMIT 100",id));if(table.equals("metal_factory"))row.put("lines",jdbc.queryForList("SELECT production_line_id,production_line_name,factory_id FROM metal_production_line WHERE factory_id=? ORDER BY production_line_id LIMIT 100",id));if(table.equals("metal_production_line"))row.put("products",jdbc.queryForList("SELECT product_id FROM metal_line_product WHERE production_line_id=? ORDER BY product_id LIMIT 100",id));if(table.equals("metal_work_order")){row.put("items",jdbc.queryForList("SELECT * FROM metal_work_order_item WHERE work_order_id=? ORDER BY item_id LIMIT 100",id));row.put("steps",jdbc.queryForList("SELECT s.* FROM metal_work_order_step s JOIN metal_work_order_item i ON i.item_id=s.item_id WHERE i.work_order_id=? ORDER BY s.item_id,s.sequence_no LIMIT 100",id));}if(warehouseFlow){row.put("groups",jdbc.queryForList("SELECT * FROM metal_warehouse_flow_group WHERE flow_id=? ORDER BY group_id LIMIT 1000",id));row.put("lines",jdbc.queryForList("SELECT l.* FROM metal_warehouse_flow_line l JOIN metal_warehouse_flow_group g ON g.group_id=l.group_id WHERE g.flow_id=? ORDER BY l.flow_line_id LIMIT 1000",id));row.put("confirmations",jdbc.queryForList("SELECT actor_id,action,version,content,create_time FROM metal_warehouse_flow_event WHERE flow_id=? ORDER BY event_id LIMIT 1000",id));}if(table.equals("metal_acid_wash_batch"))row.put("documents",jdbc.queryForList("SELECT order_id,order_no,type,status FROM metal_warehouse_order WHERE acid_wash_id=? ORDER BY order_id LIMIT 1000",id));if(table.equals("metal_warehouse_order"))row.put("lines",jdbc.queryForList("SELECT * FROM metal_warehouse_order_line WHERE order_id=? ORDER BY line_id LIMIT 100",id));if(table.equals("metal_inventory")&&c.path.matches("/metal/inventory/[0-9]+/adjust")&&result instanceof String saved&&saved.matches("[0-9]+")){var documents=jdbc.queryForList("SELECT * FROM metal_warehouse_order WHERE order_id=? AND factory_id=? AND type='ADJUST'",Long.valueOf(saved),f);if(!documents.isEmpty()){var document=documents.get(0);c.businessCode=document.get("order_no").toString();row.put("adjustmentOrder",document);}}out.put(id.toString(),AuditRedactor.redact(row));}}if(multiSubmission&&result instanceof Map<?,?> response&&Boolean.TRUE.equals(response.get("reused"))){c.replayed=true;if(c.before.isEmpty()&&!out.isEmpty()){c.before=new LinkedHashMap<>(out);c.replayBeforeFromResult=true;}}return out;}
 private List<Long> submissionOrderIds(AuditContext c,com.alibaba.fastjson2.JSONObject request){
  if(request==null||c.actorId==null||request.getString("requestId")==null)return List.of();
  Long factory=request.getLong("factoryId");
  if(factory==null||!Objects.equals(c.actorId,1L)&&!Objects.equals(c.actorFactory,factory))return List.of();
  String parent=c.path.endsWith("/inbound-submissions")?"metal_inbound_submission":"metal_outbound_submission";
  String link=c.path.endsWith("/inbound-submissions")?"inbound_submission_id":"outbound_submission_id";
  String sql="SELECT o.order_id id FROM metal_warehouse_order o JOIN metal_warehouse_flow f ON f.flow_id=o.warehouse_flow_id AND o.factory_id=f.factory_id WHERE f.request_id=? AND f.request_actor=? AND f.factory_id=? UNION SELECT o.order_id id FROM metal_warehouse_order o JOIN "+parent+" s ON s.submission_id=o."+link+" AND o.factory_id=s.factory_id WHERE s.request_id=? AND s.request_actor=? AND s.factory_id=?";
  String id=request.getString("requestId");
  return jdbc.queryForList(sql,id,c.actorId,factory,id,c.actorId,factory).stream().map(row->((Number)row.get("id")).longValue()).toList();
 }
 public void success(AuditContext c,Object after){
  var data=preparedEvent(c,"SUCCESS","",after);String payload=JSON.toJSONString(data);
  jdbc.update("INSERT INTO audit_outbox(event_id,event_json) VALUES(?,?)",c.event,payload);c.logged=true;
  if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){
   @Override public void afterCompletion(int status){
    if(status==STATUS_COMMITTED)return;
    c.logged=false;c.failureCode="SYSTEM_ERROR";
    var failed=new LinkedHashMap<String,Object>(data);failed.put("code","SYSTEM_ERROR");
    failed.put("error",status==STATUS_ROLLED_BACK?"事务最终回滚":"事务提交结果未知，需按事件ID核对");
    var changes=new LinkedHashMap<Object,Object>((Map<?,?>)data.get("changes"));changes.put("after",Map.of());
    failed.put("response","");failed.put("changes",changes);
    c.logged=persistFailure(failed);
   }
  });
 }
 private boolean persistFailure(Map<String,Object> event){try{independent.executeWithoutResult(t->jdbc.update("INSERT IGNORE INTO audit_outbox(event_id,event_json) VALUES(?,?)",event.get("event"),JSON.toJSONString(event)));return true;}catch(Exception unavailable){fallback(event);return false;}}

 public Map<String,Object> event(AuditContext c,String code,String error,Object after){Map<String,Object> e=new LinkedHashMap<>();e.put("event",c.event);e.put("trace",c.trace);e.put("actorId",c.actorId);e.put("actorFactory",c.actorFactory);e.put("actor",AuditRedactor.text(c.actor));e.put("actorName",AuditRedactor.text(c.actorName));if(c.actorFactory!=null&&c.actorId!=null&&c.actorId!=1&&!c.factories.isEmpty()&&!c.factories.contains(c.actorFactory))c.factories.add(c.actorFactory);if(c.factories.size()==1)c.businessFactory=c.factories.iterator().next();else if(c.factories.isEmpty()&&c.actorId!=null&&c.actorId!=1)c.businessFactory=c.actorFactory;e.put("factory",c.businessFactory);e.put("factories",c.factories);e.put("title",c.title);e.put("action",c.action);e.put("path",c.path);e.put("verb",c.verb);e.put("code",code);e.put("error",AuditRedactor.text(error));e.put("businessCode",c.businessCode);e.put("objectType",c.objectType);var objects=new LinkedHashMap<String,Object>(c.objectIds);objects.put("type",c.objectType);objects.put("businessCode",c.businessCode);e.put("objects",objects);e.put("request",c.request);e.put("response",c.result);e.put("replayed",c.replayed);e.put("cost",System.currentTimeMillis()-c.started);e.put("time",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).toString());var changes=new LinkedHashMap<String,Object>();changes.put("before",c.before);changes.put("after",after==null?Map.of():after);if(c.replayBeforeFromResult)changes.put("beforeSnapshotBasis","REPLAY_RETURN_STATE");e.put("changes",changes);return e;}
 private Map<String,Object> preparedEvent(AuditContext c,String code,String error,Object after){
  var data=event(c,code,error,after);
  if(c.businessFactory!=null){try{var names=jdbc.queryForList("SELECT factory_name FROM metal_factory WHERE factory_id=?",c.businessFactory);if(!names.isEmpty())data.put("factoryName",names.get(0).get("factory_name"));else data.put("factoryNameUnavailable",true);}catch(org.springframework.dao.DataAccessException unavailable){data.put("factoryNameUnavailable",true);}}
  return data;
 }
 public void failure(AuditContext c,String code,String message){if(c.logged)return;c.logged=persistFailure(preparedEvent(c,code,message,null));}
 public static synchronized void fallback(Map<String,Object> event){fallback(event,Path.of("logs/audit-fallback.jsonl"));}
 static void fallback(Map<String,Object> event,Path file){try{Files.createDirectories(file.toAbsolutePath().getParent());Files.writeString(file,JSON.toJSONString(event)+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Exception unavailable){org.slf4j.LoggerFactory.getLogger(AuditRecorder.class).error("AUDIT_FALLBACK_WRITE_FAILED event={} trace={} reason={}",event.get("event"),event.get("trace"),unavailable.getClass().getSimpleName());}}
}
